function internalCallRatio(graph, group) {
  const inGroup = new Set(group);
  const touching = graph.edges.filter((e) => inGroup.has(e.from) || inGroup.has(e.to));
  if (touching.length === 0) return 1;
  let internal = 0;
  let total = 0;
  for (const edge of touching) {
    total += edge.callsPerDay;
    if (inGroup.has(edge.from) && inGroup.has(edge.to)) internal += edge.callsPerDay;
  }
  return internal / total;
}

