function compareBoundaries(graph, groups) {
  let best = null;
  let bestScore = null;
  for (const group of groups) {
    const score = scoreBoundary(graph, group);
    if (!best || (score.verdict === 'clean' && bestScore.verdict === 'blocked') || (score.verdict === bestScore.verdict && score.internalCallRatio > bestScore.internalCallRatio)) {
      best = group;
      bestScore = score;
    }
  }
  return best;
}

