function cohesionDensity(graph, group) {
  const n = group.length;
  if (n < 2) return 0;
  const inGroup = new Set(group);
  const pairs = new Set();
  for (const e of graph.edges) {
    if (inGroup.has(e.from) && inGroup.has(e.to)) pairs.add(`${e.from}->${e.to}`);
  }
  return pairs.size / (n * (n - 1));
}

